
/**
 * Client
**/

import * as runtime from './runtime/client.js';
import $Types = runtime.Types // general types
import $Public = runtime.Types.Public
import $Utils = runtime.Types.Utils
import $Extensions = runtime.Types.Extensions
import $Result = runtime.Types.Result

export type PrismaPromise<T> = $Public.PrismaPromise<T>


/**
 * Model Tenant
 * 
 */
export type Tenant = $Result.DefaultSelection<Prisma.$TenantPayload>
/**
 * Model User
 * *
 * * Usuario dentro de un tenant (Hausdame user).
 */
export type User = $Result.DefaultSelection<Prisma.$UserPayload>
/**
 * Model CleanerProfile
 * *
 * * Perfil marketplace del cleaner
 * * Contiene información necesaria para buscar trabajo en marketplace
 */
export type CleanerProfile = $Result.DefaultSelection<Prisma.$CleanerProfilePayload>
/**
 * Model CleanerVerificationDocument
 * *
 * * Documento de verificación del cleaner (INE)
 * * Para marketplace se requiere al menos 1 INE con status APPROVED
 */
export type CleanerVerificationDocument = $Result.DefaultSelection<Prisma.$CleanerVerificationDocumentPayload>
/**
 * Model CleanerAvailabilitySlot
 * *
 * * Horarios de disponibilidad del cleaner
 * * Define disponibilidad por día de la semana
 */
export type CleanerAvailabilitySlot = $Result.DefaultSelection<Prisma.$CleanerAvailabilitySlotPayload>
/**
 * Model CleanerReview
 * *
 * * Calificación/review del cleaner
 * * Calificaciones viven en tabla separada; profile tiene agregados
 */
export type CleanerReview = $Result.DefaultSelection<Prisma.$CleanerReviewPayload>
/**
 * Model CleanerWorkFlag
 * *
 * * Bandera del cleaner para buscar trabajo
 * * Para activar se requiere: address completo + INE APPROVED
 */
export type CleanerWorkFlag = $Result.DefaultSelection<Prisma.$CleanerWorkFlagPayload>
/**
 * Model Property
 * *
 * * Propiedad / alojamiento (Airbnb u otros).
 * * FASE 5: id es el PK profesional (cuid), idOld se mantiene para auditoría
 */
export type Property = $Result.DefaultSelection<Prisma.$PropertyPayload>
/**
 * Model PropertyMemberAccess
 * 
 */
export type PropertyMemberAccess = $Result.DefaultSelection<Prisma.$PropertyMemberAccessPayload>
/**
 * Model PropertyInvite
 * 
 */
export type PropertyInvite = $Result.DefaultSelection<Prisma.$PropertyInvitePayload>
/**
 * Model PropertyAdmin
 * 
 */
export type PropertyAdmin = $Result.DefaultSelection<Prisma.$PropertyAdminPayload>
/**
 * Model PropertyCleaner
 * 
 */
export type PropertyCleaner = $Result.DefaultSelection<Prisma.$PropertyCleanerPayload>
/**
 * Model PropertyHandyman
 * 
 */
export type PropertyHandyman = $Result.DefaultSelection<Prisma.$PropertyHandymanPayload>
/**
 * Model Reservation
 * *
 * * Reserva (core Hausdame).
 * * Incluye:
 * * - Datos base de iCal (hoy)
 * * - Datos enriquecidos de correo/Sheets (futuro)
 * * - Datos de precios
 */
export type Reservation = $Result.DefaultSelection<Prisma.$ReservationPayload>
/**
 * Model Cleaning
 * *
 * * Limpieza generada a partir de una reserva
 * * (o limpiezas adicionales, futuras limpiezas intermedias).
 */
export type Cleaning = $Result.DefaultSelection<Prisma.$CleaningPayload>
/**
 * Model Lock
 * *
 * * Cerradura asociada a una propiedad.
 * * Ahora soporta TTLock, Tuya u otros proveedores.
 */
export type Lock = $Result.DefaultSelection<Prisma.$LockPayload>
/**
 * Model LockCode
 * *
 * * Código de acceso generado para una reserva en una cerradura.
 */
export type LockCode = $Result.DefaultSelection<Prisma.$LockCodePayload>
/**
 * Model MetricEvent
 * *
 * * Eventos de métricas para análisis y futuros planes SaaS.
 */
export type MetricEvent = $Result.DefaultSelection<Prisma.$MetricEventPayload>
/**
 * Model Team
 * *
 * * Equipo de limpieza
 */
export type Team = $Result.DefaultSelection<Prisma.$TeamPayload>
/**
 * Model TeamMember
 * *
 * * Miembro de un equipo de limpieza
 */
export type TeamMember = $Result.DefaultSelection<Prisma.$TeamMemberPayload>
/**
 * Model TeamMemberScheduleDay
 * *
 * * Horario de trabajo por día para un TeamMember.
 * * Permite configurar horarios distintos por día de la semana.
 */
export type TeamMemberScheduleDay = $Result.DefaultSelection<Prisma.$TeamMemberScheduleDayPayload>
/**
 * Model PropertyTeam
 * *
 * * Relación many-to-many entre Property y Team
 */
export type PropertyTeam = $Result.DefaultSelection<Prisma.$PropertyTeamPayload>
/**
 * Model HostWorkGroup
 * *
 * * Grupo de trabajo configurado por Host (tenant HOST).
 */
export type HostWorkGroup = $Result.DefaultSelection<Prisma.$HostWorkGroupPayload>
/**
 * Model HostWorkGroupProperty
 * *
 * * Relación Property <-> HostWorkGroup (tenant HOST).
 */
export type HostWorkGroupProperty = $Result.DefaultSelection<Prisma.$HostWorkGroupPropertyPayload>
/**
 * Model WorkGroupExecutor
 * *
 * * Enlace entre WorkGroup (Host) y Team (Services).
 */
export type WorkGroupExecutor = $Result.DefaultSelection<Prisma.$WorkGroupExecutorPayload>
/**
 * Model HostWorkGroupInvite
 * *
 * * Invitación para conectar un Team Leader (Cleaner) a un HostWorkGroup.
 * * El TL acepta la invitación y se crea/activa un WorkGroupExecutor.
 */
export type HostWorkGroupInvite = $Result.DefaultSelection<Prisma.$HostWorkGroupInvitePayload>
/**
 * Model CleaningAssignee
 * *
 * * Asignación de miembros a una limpieza (multi-asignación)
 */
export type CleaningAssignee = $Result.DefaultSelection<Prisma.$CleaningAssigneePayload>
/**
 * Model CleaningView
 * *
 * * Registro de "visto" de una limpieza por un miembro del equipo
 */
export type CleaningView = $Result.DefaultSelection<Prisma.$CleaningViewPayload>
/**
 * Model PropertyChecklistItem
 * *
 * * Checklist template por propiedad
 * * Define los items que deben completarse en cada limpieza de esta propiedad
 */
export type PropertyChecklistItem = $Result.DefaultSelection<Prisma.$PropertyChecklistItemPayload>
/**
 * Model CleaningChecklistItem
 * *
 * * Checklist snapshot por limpieza
 * * Copia del checklist de la propiedad al momento de crear la limpieza
 */
export type CleaningChecklistItem = $Result.DefaultSelection<Prisma.$CleaningChecklistItemPayload>
/**
 * Model Asset
 * *
 * * Asset (imágenes, archivos) - Multi-tenant
 * * Sistema de almacenamiento flexible: Supabase primero, AWS después.
 * * Usa groupId para agrupar variantes (ORIGINAL + THUMB_256).
 */
export type Asset = $Result.DefaultSelection<Prisma.$AssetPayload>
/**
 * Model InventoryItemAsset
 * *
 * * Relación entre InventoryItem y Asset (imágenes del item).
 * * Permite 1-3 imágenes por item, ordenadas por posición (1, 2, 3).
 */
export type InventoryItemAsset = $Result.DefaultSelection<Prisma.$InventoryItemAssetPayload>
/**
 * Model InventoryLineAsset
 * *
 * * Relación entre InventoryLine y Asset (imágenes de la línea específica).
 * * Fase 11: modelo híbrido — la línea tiene sus propias imágenes con fallback al InventoryItem.
 * * Permite 1-3 imágenes por línea, ordenadas por posición (1, 2, 3).
 */
export type InventoryLineAsset = $Result.DefaultSelection<Prisma.$InventoryLineAssetPayload>
/**
 * Model ChecklistItemAsset
 * *
 * * Relación entre PropertyChecklistItem y Asset (imágenes de la tarea).
 * * Permite 1-3 imágenes por tarea, ordenadas por posición (1, 2, 3).
 */
export type ChecklistItemAsset = $Result.DefaultSelection<Prisma.$ChecklistItemAssetPayload>
/**
 * Model InventoryItem
 * *
 * * Ítem de inventario (catálogo reutilizable por tenant).
 */
export type InventoryItem = $Result.DefaultSelection<Prisma.$InventoryItemPayload>
/**
 * Model VariantGroup
 * *
 * * Grupo de variantes reutilizable a nivel tenant (ej. bed_size, Tamaño de cama).
 */
export type VariantGroup = $Result.DefaultSelection<Prisma.$VariantGroupPayload>
/**
 * Model VariantOption
 * *
 * * Opción dentro de un grupo de variantes (ej. queen, king).
 */
export type VariantOption = $Result.DefaultSelection<Prisma.$VariantOptionPayload>
/**
 * Model InventoryItemVariantGroup
 * *
 * * Asociación entre InventoryItem y VariantGroup (item usa grupo).
 */
export type InventoryItemVariantGroup = $Result.DefaultSelection<Prisma.$InventoryItemVariantGroupPayload>
/**
 * Model GlobalCatalogItem
 * *
 * * Catálogo Global de Ítems (fuente única de verdad para autocomplete).
 * * No es modificable por usuarios; se actualiza mediante seeds.
 */
export type GlobalCatalogItem = $Result.DefaultSelection<Prisma.$GlobalCatalogItemPayload>
/**
 * Model InventoryLine
 * *
 * * Línea de inventario en una propiedad/área específica.
 */
export type InventoryLine = $Result.DefaultSelection<Prisma.$InventoryLinePayload>
/**
 * Model InventoryReview
 * *
 * * Revisión de inventario realizada por un Cleaner durante una limpieza.
 * * Una limpieza solo puede tener una revisión (1:1).
 */
export type InventoryReview = $Result.DefaultSelection<Prisma.$InventoryReviewPayload>
/**
 * Model InventoryCheck
 * *
 * * Verificación rápida de inventario por item durante una limpieza.
 * * Permite marcar cada item como OK / MISSING / DAMAGED sin crear una revisión completa.
 */
export type InventoryCheck = $Result.DefaultSelection<Prisma.$InventoryCheckPayload>
/**
 * Model InventoryReviewItemChange
 * *
 * * Cambio de cantidad propuesto por el Cleaner durante la revisión.
 * * Requiere aprobación del Manager/Tenant/Auxiliar antes de aplicarse al inventario oficial.
 */
export type InventoryReviewItemChange = $Result.DefaultSelection<Prisma.$InventoryReviewItemChangePayload>
/**
 * Model InventoryReport
 * *
 * * Reporte de incidencia sobre un item del inventario.
 * * Puede ser independiente o asociado a una revisión.
 */
export type InventoryReport = $Result.DefaultSelection<Prisma.$InventoryReportPayload>
/**
 * Model CleaningMedia
 * *
 * * Fotos de evidencia asociadas a una limpieza.
 * * Permite hasta 20 fotos por limpieza.
 */
export type CleaningMedia = $Result.DefaultSelection<Prisma.$CleaningMediaPayload>
/**
 * Model InventoryEvidence
 * *
 * * Evidencia (imágenes) asociada a un cambio de cantidad o reporte.
 * * Reutiliza el modelo Asset existente.
 */
export type InventoryEvidence = $Result.DefaultSelection<Prisma.$InventoryEvidencePayload>
/**
 * Model PropertyZone
 * *
 * * Zona física de una propiedad (operativa o virtual).
 * * Operativas: Sala, Cocina, Baño 1, etc.
 * * Virtuales: Almacén (STORAGE), Dañados / Baja (DAMAGED).
 */
export type PropertyZone = $Result.DefaultSelection<Prisma.$PropertyZonePayload>
/**
 * Model InventoryLog
 * *
 * * Log inmutable de eventos sobre una línea de inventario.
 * * Registra movimientos, ajustes, envíos a zonas virtuales, desactivaciones.
 */
export type InventoryLog = $Result.DefaultSelection<Prisma.$InventoryLogPayload>
/**
 * Model PropertyOpening
 * *
 * * Marketplace: Bandera de trabajo disponible por propiedad
 * * Una propiedad puede tener una bandera ACTIVE por workType (solo CLEANING en etapa 1)
 */
export type PropertyOpening = $Result.DefaultSelection<Prisma.$PropertyOpeningPayload>
/**
 * Model PropertyApplication
 * *
 * * Solicitud de un Cleaner a una PropertyOpening
 */
export type PropertyApplication = $Result.DefaultSelection<Prisma.$PropertyApplicationPayload>
/**
 * Model ChatThread
 * *
 * * Hilo de conversación (chat thread)
 * * Nace con una solicitud y continúa para el trabajo
 */
export type ChatThread = $Result.DefaultSelection<Prisma.$ChatThreadPayload>
/**
 * Model ChatParticipant
 * *
 * * Participantes de un hilo de chat
 * * REGLA DE ORO: Solo participantes activos (leftAt = null) pueden acceder al thread.
 * * Si thread.teamId existe, teamMembershipId debe estar set (TeamMembership ACTIVE requerida).
 */
export type ChatParticipant = $Result.DefaultSelection<Prisma.$ChatParticipantPayload>
/**
 * Model ChatMessage
 * *
 * * Mensaje en un hilo de chat
 */
export type ChatMessage = $Result.DefaultSelection<Prisma.$ChatMessagePayload>
/**
 * Model TeamInvite
 * 
 */
export type TeamInvite = $Result.DefaultSelection<Prisma.$TeamInvitePayload>
/**
 * Model TeamMembership
 * 
 */
export type TeamMembership = $Result.DefaultSelection<Prisma.$TeamMembershipPayload>
/**
 * Model TaskTemplate
 * Plantilla operativa que define el estándar de una propiedad
 */
export type TaskTemplate = $Result.DefaultSelection<Prisma.$TaskTemplatePayload>
/**
 * Model TaskTemplateSchedule
 * Configuración de frecuencia y carry-forward por template (1:1)
 */
export type TaskTemplateSchedule = $Result.DefaultSelection<Prisma.$TaskTemplateSchedulePayload>
/**
 * Model TaskSectionTemplate
 * Sección de una plantilla (agrupa pasos)
 */
export type TaskSectionTemplate = $Result.DefaultSelection<Prisma.$TaskSectionTemplatePayload>
/**
 * Model TaskSectionReferenceAsset
 * Imagen de referencia para una sección de plantilla
 */
export type TaskSectionReferenceAsset = $Result.DefaultSelection<Prisma.$TaskSectionReferenceAssetPayload>
/**
 * Model TaskStepTemplate
 * Paso individual dentro de una sección de plantilla
 */
export type TaskStepTemplate = $Result.DefaultSelection<Prisma.$TaskStepTemplatePayload>
/**
 * Model TaskStepOption
 * Opción seleccionable para un paso (simplificado MVP)
 */
export type TaskStepOption = $Result.DefaultSelection<Prisma.$TaskStepOptionPayload>
/**
 * Model TaskStepReferenceAsset
 * Imagen de referencia para un paso de plantilla
 */
export type TaskStepReferenceAsset = $Result.DefaultSelection<Prisma.$TaskStepReferenceAssetPayload>
/**
 * Model TaskJob
 * Job generado a partir de un template (instancia ejecutable)
 */
export type TaskJob = $Result.DefaultSelection<Prisma.$TaskJobPayload>
/**
 * Model TaskJobSection
 * Sección del job (snapshot de TaskSectionTemplate al momento de generación)
 */
export type TaskJobSection = $Result.DefaultSelection<Prisma.$TaskJobSectionPayload>
/**
 * Model TaskJobSectionResponse
 * Confirmación global de una sección (si requiresGlobalConfirm = true)
 */
export type TaskJobSectionResponse = $Result.DefaultSelection<Prisma.$TaskJobSectionResponsePayload>
/**
 * Model TaskJobSectionEvidenceAsset
 * Evidencia fotográfica adjunta a una sección del job
 */
export type TaskJobSectionEvidenceAsset = $Result.DefaultSelection<Prisma.$TaskJobSectionEvidenceAssetPayload>
/**
 * Model TaskJobStep
 * Paso del job (snapshot de TaskStepTemplate al momento de generación)
 */
export type TaskJobStep = $Result.DefaultSelection<Prisma.$TaskJobStepPayload>
/**
 * Model TaskJobStepResponse
 * Respuesta del cleaner a un paso (una sola respuesta vigente por paso)
 */
export type TaskJobStepResponse = $Result.DefaultSelection<Prisma.$TaskJobStepResponsePayload>
/**
 * Model TaskJobStepEvidenceAsset
 * Evidencia fotográfica adjunta a un paso del job
 */
export type TaskJobStepEvidenceAsset = $Result.DefaultSelection<Prisma.$TaskJobStepEvidenceAssetPayload>
/**
 * Model TaskCarryForward
 * Carry-forward: tarea diferida que se inyecta en el siguiente job elegible
 */
export type TaskCarryForward = $Result.DefaultSelection<Prisma.$TaskCarryForwardPayload>
/**
 * Model TaskJobEventLog
 * Log de eventos de un job (auditoría inmutable)
 */
export type TaskJobEventLog = $Result.DefaultSelection<Prisma.$TaskJobEventLogPayload>
/**
 * Model TaskRecurringDue
 * Obligación operativa periódica — representa que una actividad ha vencido
 * y debe resolverse dentro de una limpieza real.
 * No es una ejecución; es una deuda. La ejecución sigue ocurriendo dentro
 * de una limpieza real a través de syncTaskJobsForCleaning.
 * 
 * Deduplicación: @@unique([tenantId, templateId, periodKey]) evita duplicados
 * del mismo período. Si existe una obligación abierta (PENDING_ASSIGNMENT o ASSIGNED)
 * para un template, el siguiente período no crea una nueva hasta que se resuelva.
 */
export type TaskRecurringDue = $Result.DefaultSelection<Prisma.$TaskRecurringDuePayload>

